return {api_version=1,id="EX1_304",name="Void Terror",text="[x]<b>Battlecry:</b> Destroy both\nadjacent minions and gain\n their Attack and Health.",set="EXPERT1",type="minion",class="warlock",rarity="rare",cost=3,attack=3,health=4,tags={"demon"},keywords={"battlecry"},on_battlecry=function(ctx,self)local adjacent=ctx:adjacent_minions(self);local a,h=0,0;for _,e in ipairs(adjacent)do local x=ctx:entity(e);a=a+x.attack;h=h+x.health end;if #adjacent>0 then cardlib.effects.destroy_all(ctx, adjacent);cardlib.effects.buff(ctx, self,a,h)end end}
